// Stock signals exactly as A7's 19c Prop verdict reads them (A7 eefd6c42, lines 41-50): class stock available / unavailable,
// the schema.org availability, and pre-order words. One signal = that stock; none = not_found; more than one kind = conflicting.
function read(html) {
  const h = String(html || '');
  const text = h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  const signals = [];
  if (/class="[^"]*\bstock\b[^"]*\bavailable\b/i.test(h)) signals.push('in_stock');
  if (/class="[^"]*\bstock\b[^"]*\bunavailable\b/i.test(h)) signals.push('out_of_stock');
  const ld = h.match(/"availability"\s*:\s*"[^"]*schema\.org\/(InStock|OutOfStock|PreOrder|SoldOut|Discontinued)"/i);
  if (ld) signals.push(/instock/i.test(ld[1]) ? 'in_stock' : (/preorder/i.test(ld[1]) ? 'pre_order' : 'out_of_stock'));
  if (/\bpre[-\s]?order\b/i.test(text) && /add to cart|pre[-\s]?order now/i.test(text)) signals.push('pre_order');
  const uniq = Array.from(new Set(signals));
  const stock = uniq.length === 1 ? uniq[0] : (uniq.length ? 'conflicting' : 'not_found');
  const sku = text.match(/\bSKU\s*:?\s*([A-Za-z0-9-]{3,20})\b/);
  const near = (h.match(/class="[^"]*\bstock\b[^"]*"[^>]*>[\s\S]{0,120}/i) || [''])[0].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 140);
  return { stock, signals: uniq, sku_on_page: sku ? sku[1] : '', stock_element: near };
}
const pages = $('Lamp pages').all().map(x => x.json);
return $input.all().map((it, i) => {
  const r = it.json || {};
  const html = String(r.body || r.data || '');
  const got = read(html);
  return { json: { sku_asked: pages[i].sku, url: pages[i].url, http_status: r.statusCode || null, stock: got.stock, signals: got.signals, sku_on_page: got.sku_on_page, stock_element: got.stock_element, bytes: html.length, read_at: new Date().toISOString() } };
});
